from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    stack, groups = [], []
    for char in paren_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            group = ''
            while stack and stack[-1] == '(':
                group = stack.pop() + group
            if stack:
                stack.pop()
            groups.append(group)
    return groups
