from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def find_group(s: str, start: int, depth: int) -> str:
        result = ''
        for i in range(start, len(s)):
            if s[i] == '(':
                depth += 1
                result += s[i]
            elif s[i] == ')':
                depth -= 1
                result += s[i]
                if depth == 0:
                    return result
            else:
                result += s[i]
        return ''

    groups = []
    i = 0
    while i < len(paren_string):
        if paren_string[i] == '(':
            group = find_group(paren_string, i, 0)
            groups.append(group)
            i += len(group)
        else:
            i += 1
    return groups
```

