from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    def find_groups(s: str, start: int, end: int):
        stack = []
        for i in range(start, end):
            if s[i] == '(':
                stack.append(i)
            elif s[i] == ')':
                j = stack.pop()
                group = s[j:i+1]
                if not stack:
                    yield group

    s = paren_string.replace(' ', '')
    groups = []
    i = 0
    while i < len(s):
        if s[i] == '(':
            end = find_group_end(s, i)
            group = ''.join(find_groups(s, i, end))
            groups.append(group)
            i = end
        else:
            i += 1
    return groups

def find_group_end(s: str, start: int):
    stack = []
    for i in range(start, len(s)):
        if s[i] == '(':
            stack.append(i)
        elif s[i] == ')':
            j = stack.pop()
            if not stack:
                return i
```

