def parse_nested_parens(paren_string: str) -> List[int]:
    def count_nested_parens(group: str) -> int:
        depth = 0
        max_depth = 0
        for char in group:
            if char == '(':
                depth += 1
                max_depth = max(max_depth, depth)
            elif char == ')':
                depth -= 1
        return max_depth

    groups = paren_string.split()
    return [count_nested_parens(group) for group in groups]
