def is_palindrome(string: str) -> bool:
    """ Test if given string is a palindrome """
    return string == string[::-1]


def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> make_palindrome('')
    ''
    >>> make_palindrome('cat')
    'catac'
    >>> make_palindrome('cata')
    'catac'
    """
    def is_substring_palindrome(string: str, start: int) -> int:
        for i in range(start, len(string)):
            if string[i]!= string[start - 1]:
                return start - 1
        return len(string)

    for i in range(len(string), 0, -1):
        if is_palindrome(string[i:]):
            return string + string[:i][::-1]

    return string
```

```python
def make_palindrome(string: str) -> str:
    """ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> make_palindrome('')
    ''
    >>> make_palindrome('cat')
    'catac'
    >>> make_palindrome('cata')
    'catac'
    """
    def is_palindrome(s: str) -> bool:
        """ Test if given string is a palindrome """
        return s == s[::-1]

    def longest_palindrome_suffix(s: str) -> str:
        """ Find the longest palindrome suffix of a given string """
        for i in range(len(s), 0, -1):
            if is_palindrome(s[-i:]):
                return s[-i:]

    def reverse_prefix(s: str, prefix: str) -> str:
        """ Reverse a prefix of a given string """
        return prefix + s[len(prefix):][::-1]

    if not string:
        return string
    else:
        suffix = longest_palindrome_suffix(string)
        return string + reverse_prefix(string, string[len(suffix):])
```

