def parse_music(music_string: str) -> List[int]:
    notes = {
        'o': 4,
        'o|': 2,
        '.|': 1
    }

    result = []
    note = ''

    for char in music_string:
        if char in notes:
            note += char
        else:
            if note:
                result.extend([notes[note[:i+1]] for i in range(len(note)) if note[i:i+1] in notes])
                note = ''

    if note:
        result.extend([notes[note[:i+1]] for i in range(len(note)) if note[i:i+1] in notes])

    return result
