```python
def how_many_times(string: str, substring: str) -> int:
    count = 0
    index = 0
    while index < len(string):
        index = string.find(substring, index)
        if index!= -1:
            count += 1
            index += 1
        else:
            break
    return count
```

```python
def how_many_times(string: str, substring: str) -> int:
    count = 0
    i = 0
    while i < len(string):
        if string[i:i+len(substring)] == substring:
            count += 1
        i += 1
    return count
```

