def modp(n: int, p: int) -> int:
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * pow(2, p - 2, p)) % p
        n = n // 2
    return result % p
```

```python
def modp(n: int, p: int):
    if p == 1:
        return 1
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * pow(2, p-2, p)) % p
        n = n >> 1
        p = (p * p) % 65536
    return result
```

```python
def modp(n: int, p: int) -> int:
    if p == 1:
        return 1
    result = 1
    while n:
        if n % 2:
            result = (result * n) % p
        n //= 2
        p = (p * p) % p
    return result
```

