            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    count = 0
    for digit in num:
        if digit in '234567':
            count += 1
        elif digit in 'BDF':
            count += 1
    return count
