        1.7: 'C', 
        1.3: 'C-', 
        1.0: 'D+', 
        0.7: 'D', 
        0.0: 'D-'
    }

    result = []
    for grade in grades:
        if grade == 0:
            result.append('E')
        elif grade in letter_grades:
            result.append(letter_grades[grade])
        elif grade > 4:
            raise ValueError('GPA cannot be greater than 4.0')
        else:
            if grade > 3.7:
                result.append('A')
            elif grade > 3.3:
                result.append('A-')
            elif grade > 3.0:
                result.append('B+')
            elif grade > 2.7:
