```python
def sort_array(array):
    if len(array) < 2:
        return array[:]
    sum_first_last = array[0] + array[-1]
    if sum_first_last % 2 == 0:
        return sorted(array)[::-1]
    return sorted(array)
```

```python
def encrypt(s):
    shift = 2 * 2
    result = ""
    for char in s:
        if char.isalpha():
            ascii_offset = 97 if char.islower() else 65
            result += chr((ord(char) - ascii_offset + shift) % 26 + ascii_offset)
        else:
            result += char
    return result
```

