def encrypt(s):
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    result = ''
    for char in s:
        if char.isalpha():
            if char.islower():
                shift = 2 * 2
            else:
                shift = 2 * 2
            result += alphabet[(alphabet.index(char.lower()) + shift) % 26]
        else:
            result += char
    return result
```

