def make_a_pile(n):
    pile = [n]
    is_odd = n % 2!= 0
    for _ in range(1, n):
        if is_odd:
            pile.append(pile[-1] + 2)
        else:
            pile.append(pile[-1] + 1)
        is_odd = not is_odd
    return pile
```

