def exchange(lst1, lst2):
    def can_make_even(lst):
        return all(num % 2 == 0 for num in lst)

    lst1_copy = lst1[:]
    for num in lst1_copy:
        if num % 2!= 0:
            if num in lst2:
                lst1_copy.remove(num)
                lst1.append(num)
                if can_make_even(lst1_copy):
                    return "YES"
                else:
                    lst1.pop()
                    lst1_copy.append(num)
    return "NO"
```

