def minSubArraySum(nums):
    min_sum = float('inf')
    curr_sum = 0
    for num in nums:
        curr_sum += num
        min_sum = min(min_sum, curr_sum)
        if curr_sum > 0:
            curr_sum = 0
    return min(min_sum, min([sum(sub_arr) for sub_arr in (nums[i:] for i in range(len(nums)))]))
```

