    n = len(grid)
    m = len(grid[0])
    buckets = 0
    for col in range(m):
        water = 0
        for row in range(n):
            if grid[row][col] == 1:
                water += 1
        if water % capacity == 0:
            buckets += water // capacity
        else:
            buckets += water // capacity + 1
    return buckets
