def get_odd_collatz(n):
    def collatz(n):
        sequence = [n]
        while n!= 1:
            if n % 2 == 0:
                n = n // 2
            else:
                n = n * 3 + 1
            sequence.append(n)
        return sequence

    sequence = collatz(n)
    return sorted(set([num for num in sequence if num % 2!= 0]))
```

