def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.
    """
    def collatz(n, odd_numbers):
        if n == 1:
            return odd_numbers
        if n % 2 == 0:
            return collatz(n // 2, odd_numbers)
        else:
            return collatz(n * 3 + 1, odd_numbers + [n])
    return sorted(collatz(n, [n]))
```

