def get_odd_collatz(n):
    collatz = set()
    while n!= 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        collatz.add(n)
    odd_collatz = sorted([num for num in collatz if num % 2!= 0])
    if 1 not in odd_collatz:
        odd_collatz.append(1)
    return odd_collatz
```

```python
def valid_date(date):
    try:
        month, day, year = map(int, date.split('-'))
        if date.count('-')!= 2:
            return False
        if month < 1 or month > 12:
            return False
        if day < 1:
            return False
        if (month in [1, 3, 5, 7, 8, 10, 12] and day > 31) or \
           (month in [4, 6, 9, 11] and day > 30) or \
           (month == 2 and (day > 29 or (day == 29 and not is_leap_year(year)))):
            return False
        return True
    except ValueError:
        return False

def is_leap_year(year):
    return year % 4 == 0 and (year % 100!= 0 or year % 400 == 0)
```

