from calendar import monthrange

def valid_date(date):
    try:
        mm, dd, yyyy = map(int, date.split('-'))
        if len(date.split('-'))!= 3 or mm < 1 or mm > 12 or dd < 1 or dd > 31:
            return False
        if mm in [1, 3, 5, 7, 8, 10, 12]:
            max_days = 31
        elif mm in [4, 6, 9, 11]:
            max_days = 30
        elif mm == 2:
            max_days = 29
            if yyyy % 4 == 0 and (yyyy % 100!= 0 or yyyy % 400 == 0):
                max_days = 29
        else:
            return False
        return monthrange(yyyy, mm)[1] >= dd
    except ValueError:
        return False
```

