import heapq

def minPath(grid, k):
    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    heap = []
    visited = set()
    for i in range(m):
        for j in range(n):
            heapq.heappush(heap, (grid[i][j], (i, j, 0, [grid[i][j]])))
    while heap:
        val, (x, y, step, path) = heapq.heappop(heap)
        if step == k:
            return path
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and (nx, ny, step + 1, path + [grid[nx][ny]]) not in visited:
                heapq.heappush(heap, (val, (nx, ny, step + 1, path + [grid[nx][ny]])))
                visited.add((nx, ny, step + 1, path + [grid[nx][ny]]))
    return []
