import heapq
from collections import deque

def minPath(grid, k):
    N = len(grid)
    visited = set()
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    pq = []
    result = []

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def push(x, y, dist, val):
        if (x, y) in visited:
            return
        heapq.heappush(pq, (dist, val, x, y))
        visited.add((x, y))

    for i in range(N):
        for j in range(N):
            push(i, j, 0, grid[i][j])

    for _ in range(k):
        dist, val, x, y = heapq.heappop(pq)
        result.append(val)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                push(nx, ny, dist + 1, grid[nx][ny])

    return result
```

