from heapq import heappop, heappush
from collections import deque

def minPath(grid, k):
    n = len(grid)
    visited = set((x, y, []) for x in range(n) for y in range(n))
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def neighbors(x, y):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n:
                yield nx, ny

    def h(cell):
        return cell[2][0]

    pq = [(0, 0, 0, [])]
    while pq:
        _, x, y, path = heappop(pq)
        if len(path) == k:
            return path + [grid[x][y]]
        for nx, ny in neighbors(x, y):
            if (nx, ny, path) not in visited:
                visited.add((nx, ny, path + [grid[x][y]]))
                heappush(pq, (h((nx, ny, path + [grid[x][y]])), nx, ny, path + [grid[x][y]]))

    return []
