    sequence = [1, 3]
    while len(sequence) < n + 1:
        if len(sequence) == 1:
            sequence.append(3)
        elif sequence[-1] % 2 == 0:
            sequence.append(1 + sequence[-1] / 2)
        else:
            sequence.append(sequence[-2] + sequence[-3] + sequence[-4])
    return sequence[:n + 1]
```

