def tri(n):
    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]
    elif n == 2:
        return [1, 3, 2]
    else:
        sequence = [1, 3, 2]
        while len(sequence) <= n:
            if len(sequence) % 2 == 0:
                sequence.append(1 + (len(sequence) - 1) / 2)
            else:
                sequence.append(sequence[-1] + sequence[-2] + (sequence[-3] if len(sequence) > 2 else 2))
        return sequence[:n+1]
```

