def tri(n):
    sequence = [1, 3]
    while len(sequence) < n + 1:
        if sequence[-1] % 2 == 0:
            sequence.append(1 + sequence[-1] / 2)
        else:
            if len(sequence) < 3:
                sequence.append(sequence[-1])
            else:
                sequence.append(sequence[-2] + sequence[-3] + sequence[-1])
    return sequence
