```python
def file_name_check(file_name):
    if len(file_name) < 4 or file_name[-4:] not in ['txt', 'exe', 'dll']:
        return 'No'
    if file_name.count('.')!= 1:
        return 'No'
    name_before_dot = file_name.split('.')[0]
    if len(name_before_dot) == 0 or not name_before_dot[0].isalpha():
        return 'No'
    if sum(c.isdigit() for c in name_before_dot) > 3:
        return 'No'
    return 'Yes'
```

```python
def file_name_check(file_name):
    parts = file_name.split('.')
    if len(parts)!= 2:
        return 'No'
    if not parts[0][0].isalpha():
        return 'No'
    if len(parts[0]) > 1 and not parts[0][1:].isalnum():
        return 'No'
    if sum(c.isdigit() for c in parts[0]) > 3:
        return 'No'
    if sum(c.isdigit() for c in parts[1]) > 0:
        return 'No'
    if parts[1] not in ['txt', 'exe', 'dll']:
        return 'No'
    return 'Yes'
```

```python
def file_name_check(file_name):
    if len(file_name) < 5 or len(file_name) > 30:
        return 'No'
    if file_name.count('.')!= 1:
        return 'No'
    name_before_dot, name_after_dot = file_name.rsplit('.', 1)
    if not name_before_dot or not name_before_dot[0].isalpha():
        return 'No'
    if len([char for char in name_before_dot if char.isdigit()]) > 3:
        return 'No'
    valid_extensions = ['txt', 'exe', 'dll']
    if name_after_dot not in valid_extensions:
        return 'No'
    return 'Yes'
```

