def file_name_check(file_name):
    if len(file_name) == 0:
        return 'No'
    if file_name.count('.')!= 1:
        return 'No'
    name, extension = file_name.split('.')
    if not name[0].isalpha() or len(name) > 1 and not name[1:].replace('.', '', 1).isalnum():
        return 'No'
    if not extension in ['txt', 'exe', 'dll']:
        return 'No'
    digits = sum(c.isdigit() for c in name)
    return 'Yes' if digits <= 3 else 'No'
```

