def file_name_check(file_name):
    if len(file_name) < 1 or len(file_name) > 255:
        return 'No'
    if len(file_name)!= file_name.count('.') + 1:
        return 'No'
    name_parts = file_name.split('.')
    if len(name_parts[0]) < 1 or not name_parts[0][0].isalpha():
        return 'No'
    if len(name_parts)!= 2:
        return 'No'
    if len(name_parts[1]) > 4 or len(name_parts[1]) < 1:
        return 'No'
    if not name_parts[1].lower() in ['txt', 'exe', 'dll']:
        return 'No'
    if sum(c.isdigit() for c in name_parts[0]) > 3:
        return 'No'
    return 'Yes'
```

