def get_max_triples(n):
    count = 0
    a = [i * i - i + 1 for i in range(1, n + 1)]
    a.sort()
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            total = a[i] + a[left] + a[right]
            if total % 3 == 0:
                count += 1
                left += 1
            elif total < 3:
                left += 1
            else:
                right -= 1
    return count
```

