    def count_unique_chars(word):
        return len(set(word))

    max_unique = 0
    result = ""
    for word in words:
        unique_chars = count_unique_chars(word)
        if unique_chars > max_unique or (unique_chars == max_unique and word < result):
            max_unique = unique_chars
            result = word

    return result
