def is_woodall(n):
    sum = 0
    i = 1
    while sum < n:
        sum += i ** prime_factors(i)
        i += 1
    return sum == n

def prime_factors(n):
    i = 2
    factors = 0
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors += 1
    if n > 1:
        factors += 1
    return factors
```

