def count_Substrings(s):
    def sum_to_len(i):
        return sum(int(c) for c in s[i:i+length])

    count = 0
    for length in range(1, len(s)+1):
        for i in range(len(s) - length + 1):
            if sum_to_len(i) == length:
                count += 1
    return count
