from functools import lru_cache

@lru_cache(maxsize=None)
def catalan(n):
    if n == 0 or n == 1:
        return 1
    catalan_dict = {0: 1, 1: 1}
    for i in range(2, n + 1):
        catalan_dict[i] = 0
        for j in range(i):
            catalan_dict[i] += catalan_dict[j] * catalan_dict[i - j - 1]
    return catalan_dict[n]

def bell_number(n):
    return catalan(n + 1)
```

