```python
def next_smallest_palindrome(n):
    def is_palindrome(x):
        return str(x) == str(x)[::-1]

    def next_num(x):
        return x + 1

    if is_palindrome(n):
        return n

    while True:
        n = next_num(n)
        if is_palindrome(n):
            return n
```

