def next_smallest_palindrome(n):
    def is_palindrome(x):
        return str(x) == str(x)[::-1]

    def next_number(x):
        return x + 1

    if is_palindrome(n):
        return n

    lower_bound = n
    upper_bound = n + 1

    while True:
        if is_palindrome(upper_bound):
            return upper_bound
        upper_bound = next_number(upper_bound)
        if upper_bound > lower_bound * 10:
            lower_bound = lower_bound + 1
            upper_bound = lower_bound * 10
```

