def common_in_nested_lists(nested_lists: List[List[int]]) -> List[int]:
    def find_common(lst, common):
        if not lst:
            return common
        common = [num for num in common if num in lst]
        common = [num for num in common if lst.count(num) > 1]
        return find_common(lst[1:], common)

    if not nested_lists:
        return []

    common = find_common(nested_lists[0], nested_lists[0])
    for lst in nested_lists[1:]:
        common = find_common(lst, common)

    return common
```

