def sum(a, b):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a
    def sum_divisors(n):
        return sum(i for i in range(1, n + 1) if n % i == 0)
    return sum_divisors(gcd(a, b)) + sum_divisors(a) + sum_divisors(b) - sum_divisors(a * b)
```

