    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def sum_of_divisors(n):
        sum_divisors = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                sum_divisors += i
                if i!= n // i:
                    sum_divisors += n // i
        return sum_divisors

    return sum_of_divisors(gcd(a, b)) - a - b
