def magic_square_test(matrix):
    target = sum(matrix[0])  # Calculate the target sum
    for row in matrix:
        if sum(row)!= target:
            return False
    for col in range(len(matrix[0])):
        if sum(matrix[row][col] for row in range(len(matrix)))!= target:
            return False
    if sum(matrix[i][i] for i in range(len(matrix)))!= target:
        return False
    if sum(matrix[i][len(matrix) - i - 1] for i in range(len(matrix)))!= target:
        return False
    return True
