def find_even_pair(nums):
    even_count = 0
    xor_count = {}
    for num in nums:
        xor_count[num] = xor_count.get(num, 0) + 1
    for num in xor_count:
        if xor_count.get(num, 0) > 1 or (num ^ num) % 2 == 0:
            even_count += (xor_count[num] * (xor_count[num] - 1)) // 2
    return even_count
```

