def is_majority(arr, n, target):
    count = 0
    for i in range(n):
        if arr[i] == target:
            count += 1
        else:
            count -= 1
        if count == 0:
            left, right = i - 1, i + 1
            while left >= 0 and arr[left]!= target:
                left -= 1
            while right < n and arr[right]!= target:
                right += 1
            if right - left > n // 2:
                return True
    return False
```

