def re_arrange_array(arr, n):
    negative = [x for x in arr[:n] if x < 0]
    positive = [x for x in arr[:n] if x >= 0]
    return negative + [x for x in arr[n:] if x < 0] + sorted([x for x in arr[n:] if x >= 0], key=lambda x: arr.index(x))
```

