def re_arrange_array(arr, n):
    negative = [x for x in arr[:n] if x < 0]
    positive = [x for x in arr[:n] if x >= 0]
    return negative + [x for x in arr[n:] if x < 0] + sorted([x for x in arr[n:] if x >= 0])
```

```python
def re_arrange_array(arr, n):
    neg, pos = [], []
    for i in range(n):
        if arr[i] < 0:
            neg.append(arr[i])
        else:
            pos.append(arr[i])
    neg += sorted([x for x in arr[n:] if x < 0], key=lambda x: arr.index(x))
    pos += sorted([x for x in arr[n:] if x >= 0], key=lambda x: arr.index(x))
    return neg + pos
```

