def check_occurences(tuples):
    occurrences = {}
    for t in tuples:
        reversed_t = tuple(reversed(t))
        if reversed_t in occurrences:
            occurrences[reversed_t] += 1
        else:
            occurrences[reversed_t] = 1
    return occurrences
