def check_occurences(tuples_list):
    unique_tuples = set()
    occurrences = {}
    for tup in tuples_list:
        sorted_tup = tuple(sorted(tup))
        if sorted_tup not in unique_tuples:
            unique_tuples.add(sorted_tup)
            occurrences[sorted_tup] = 1
        else:
            occurrences[sorted_tup] += 1
    return occurrences
```

