def get_total_number_of_sequences(m, n):
    if n == 1:
        return m
    else:
        dp = [0] * (m + 1)
        dp[1] = m
        for i in range(2, n + 1):
            for j in range(1, m + 1):
                for k in range(1, j):
                    if 2 * k <= j < m and j >= 2 * (i - 2):
                        dp[j] += dp[k]
        return dp[m]
```

```python
def get_total_number_of_sequences(m, n):
    @cache
    def dp(i, j):
        if i == 1:
            return 1 if j >= 1 and j <= m else 0
        res = 0
        for k in range(2 * j, min(m, j + 1) + 1):
            res += dp(i - 1, k)
        return res

    return dp(n, 1)
```

```python
def get_total_number_of_sequences(m, n):
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        dp[i][1] = 1
    for j in range(2, n+1):
        for i in range(2, m+1):
            dp[i][j] = sum(dp[min(2*i, m)-k][j-1] for k in range(1, min(2*i, m)+1))
    return sum(dp[i][n] for i in range(2, m+1))
```

