def get_total_number_of_sequences(m, n):
    def get_total_number_of_sequences_helper(m, n, i, prev):
        if i == n:
            return 1
        total = 0
        for x in range(1, m // (2 * prev) + 1):
            total += get_total_number_of_sequences_helper(m, n, i + 1, x)
        return total

    return get_total_number_of_sequences_helper(m, n, 1, m)
