def get_total_number_of_sequences(m, n):
    def get_total_number_of_sequences_helper(m, n, current_number, previous_number):
        if n == 0:
            return 1
        total = 0
        for i in range(current_number, m, 1):
            if i >= 2 * previous_number:
                total += get_total_number_of_sequences_helper(m, n - 1, i, i)
        return total

    return get_total_number_of_sequences_helper(m, n, 1, 1)
