    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
    for i in range(2, m + 1):
        for j in range(2, n + 1):
            for k in range(1, (i // 2) + 1):
                dp[i][j] += dp[i - 2 * k][j - 1]
    return dp[m][n]
