def get_total_number_of_sequences(m, n):
    def get_sequences(m, n, current=1, sequence=[]):
        if len(sequence) == n:
            return [sequence]
        count = 0
        for i in range((sequence[-1] if sequence else current) * 2 + 1, m + 1):
            count += get_sequences(m, n, i, sequence + [i])
        return count
    return get_sequences(m, n)
```

