def lps(s):
    def is_palindrome(s):
        return s == s[::-1]

    def longest_palindromic_subsequence(s, start):
        if start == len(s):
            return 0
        max_length = 0
        for end in range(start, len(s)):
            substring = s[start:end+1]
            if is_palindrome(substring):
                max_length = max(max_length, 1 + longest_palindromic_subsequence(s, end+1))
        return max_length

    return longest_palindromic_subsequence(s, 0)
```

