def find_star_num(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    def count_primes(num):
        count = 0
        for i in range(2, num):
            if is_prime(i):
                count += 1
        return count

    star_nums = []
    i = 1
    while len(star_nums) < n:
        if is_prime(i) and count_primes(i) == count_primes(i - 1):
            star_nums.append(i)
        i += 1
    return star_nums[-1]
```

