def max_sub_array_sum_repeated(arr, k, n):
    max_sum = float('-inf')
    for i in range(n):
        for j in range(i, n):
            sub_sum = sum(arr[i//k:i//k+k] if i % k == 0 else arr[(i-1)//k+1:i//k+1])
            for _ in range(1, k):
                sub_sum = max(sub_sum, sum(arr[i//k+i%k:i//k+i%k+k]))
            max_sum = max(max_sum, sub_sum)
    return max_sum
```

