def get_Inv_Count(arr):
    if len(arr) == 1:
        return 0
    count = 0
    mid = len(arr) // 2
    left = get_Inv_Count(arr[:mid])
    right = get_Inv_Count(arr[mid:])
    for i in range(mid, len(arr)):
        for j in range(i - mid, -1, -1):
            if arr[j] > arr[i]:
                count += 1
    return count + left + right
```

