def max_sum_increasing_subseq(arr, n, i, k):
    def max_sum(prefix, start, end):
        if start == end:
            return prefix[start]
        max_sum_left = max_sum(prefix, start, (start + end) // 2)
        max_sum_right = max_sum(prefix, (start + end) // 2 + 1, end)
        if arr[prefix[(start + end) // 2]] <= arr[k]:
            return max(max_sum_left, max_sum_right)
        else:
            return max_sum_left + arr[k]

    prefix = [0] * (i + 1)
    for j in range(1, i + 1):
        prefix[j] = prefix[j - 1] + arr[j - 1]

    return max_sum(prefix, 0, i)
```

