def max_sum_increasing_subseq(arr, n, i, k):
    prefix = [0] * (i + 1)
    for j in range(i + 1):
        if j == 0:
            prefix[j] = arr[j]
        else:
            prefix[j] = max(prefix[j-1], arr[j] + prefix[j-1] - arr[j-1])

    max_sum = prefix[i]
    for j in range(i + 1, k):
        if j == i + 1:
            max_sum = max(max_sum, arr[j])
        else:
            max_sum = max(max_sum, arr[j] + prefix[j-1] - arr[j-1])

    return max_sum
```

