def max_sum_increasing_subseq(arr, n, i, k):
    def max_sum(prefix, i, k):
        if k == i + 1:
            return prefix[i]
        elif k == n + 1:
            return prefix[i] + prefix[k-1]
        elif prefix[k-1] > prefix[i]:
            return max_sum(prefix, i, k+1)
        else:
            return max(prefix[i] + max_sum(prefix, i+1, k+1), max_sum(prefix, i, k+1))

    prefix = [0] * (n + 1)
    for j in range(1, n + 1):
        prefix[j] = max(prefix[j-1], arr[j-1] + prefix[j-1])
    return max_sum(prefix, i, i+1)
```

