def get_max_sum(n):
    memo = {1: 1}
    def f(n):
        if n in memo: return memo[n]
        res = n
        for d in [2, 3, 4, 5]:
            if n % d == 0:
                res = max(res, f(n//d) + f(n))
        memo[n] = res
        return res
    return f(n)
