def get_max_sum(n):
    @lru_cache(maxsize=None)
    def f(n):
        if n <= 1:
            return n
        return max(n + f(n//2) + f(n//3) + f(n//4) + f(n//5), f(n//2) + f(n//3) + f(n//4) + f(n//5))
    return f(n)
