def get_max_sum(n, memo={}):
    if n in memo:
        return memo[n]
    if n < 5:
        memo[n] = n
        return n
    max_sum = n
    for d in [2, 3, 4, 5]:
        max_sum = max(max_sum, get_max_sum(n//d, memo) + get_max_sum(n, memo))
    memo[n] = max_sum
    return max_sum
```

