def rearrange_bigger(n):
    n = list(str(n))
    for i in range(len(n)-2, -1, -1):
        if n[i] < n[i+1]:
            break
    else:
        return False
    for j in range(len(n)-1, i, -1):
        if n[i] < n[j]:
            n[i], n[j] = n[j], n[i]
            n[i+1:] = sorted(n[i+1:])
            return int(''.join(n))
    return False
```

