def rearrange_bigger(n):
    num = list(str(n))
    if sorted(num)!= list(num):
        i = len(num) - 1
        while i > 0 and num[i-1] >= num[i]:
            i -= 1
        if i <= 0:
            return False
        j = len(num) - 1
        while num[j] <= num[i-1]:
            j -= 1
        num[i-1], num[j] = num[j], num[i-1]
        num[i:] = num[i:][::-1]
        return int(''.join(num))
    else:
        return False
```

