import heapq

def k_smallest_pairs(arr1, arr2, k):
    min_heap = []
    for num1 in arr1:
        for num2 in arr2:
            heapq.heappush(min_heap, [num1 + num2, [num1, num2]])
            if len(min_heap) > k:
                heapq.heappop(min_heap)
    return [pair[1] for pair in min_heap]
