def group_tuples(tuples):
    first_elements = {}
    for t in tuples:
        first = t[0]
        if first in first_elements:
            first_elements[first].append(t)
        else:
            first_elements[first] = [t]
    result = []
    for key in first_elements:
        result.append(list(map(lambda x: x[0], first_elements[key])))
        for i in range(1, len(first_elements[key])):
            result[-1].append(first_elements[key][i][1])
    return result
```

