def group_tuples(tuples_list):
    first_elements = {}
    for t in tuples_list:
        first = t[0]
        if first not in first_elements:
            first_elements[first] = []
        first_elements[first].append(t)

    result = []
    for key in first_elements:
        grouped = list(zip(*first_elements[key]))
        result.append(tuple(grouped[0]))

    return result
