```python
def group_tuples(tuples_list):
    groups = {}
    for t in tuples_list:
        key = t[0]
        if key in groups:
            groups[key].append(t)
        else:
            groups[key] = [t]
    result = []
    for key, group in groups.items():
        if len(group) > 1:
            common = group[0]
            for t in group:
                common = tuple(a if a == b else None for a, b in zip(common, t))
                common = tuple(a for a in common if a is not None)
            result.append(common)
        else:
            result.append(group[0])
    return result
```
